-- B.R.A.N.D 2.0
-- Canonical 34-character-collection sync from user TSV.
-- Source SHA-256: e6ad02caa122842acb7e295f81d78fbaee20fd62b6f3bc9e49d2d4225d161686
-- Preserves collection IDs; stale members/rewards are deactivated rather than deleted.
BEGIN;
CREATE TEMP TABLE desired_character_collections(collection_uid varchar PRIMARY KEY,name varchar NOT NULL,collection_class varchar NOT NULL,description text NOT NULL,effect_code varchar NOT NULL,effect_value numeric NOT NULL,is_active boolean NOT NULL,is_visible boolean NOT NULL,sort_order integer NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE desired_character_collection_members(collection_uid varchar NOT NULL,character_uid varchar NOT NULL,sort_order integer NOT NULL,PRIMARY KEY(collection_uid,character_uid)) ON COMMIT DROP;
DO $$ DECLARE v_classroom_id integer; BEGIN SELECT id INTO v_classroom_id FROM public.classrooms WHERE school_year=2026 AND grade_level=5 AND name='5학년 4반' AND is_active ORDER BY id LIMIT 1; IF v_classroom_id IS NULL THEN RAISE EXCEPTION 'Target classroom 2026 5학년 4반 not found'; END IF; IF EXISTS(SELECT 1 FROM desired_character_collection_members d LEFT JOIN public.characters c ON c.character_uid=d.character_uid WHERE c.id IS NULL) THEN RAISE EXCEPTION 'Canonical collection file references unknown character_uid'; END IF; IF EXISTS(SELECT 1 FROM desired_character_collections d LEFT JOIN public.buff_effect_catalog e ON e.effect_code=d.effect_code AND e.is_active WHERE e.id IS NULL) THEN RAISE EXCEPTION 'Canonical collection file references unknown/inactive effect_code'; END IF; IF EXISTS(SELECT 1 FROM desired_character_collections d JOIN public.character_collections c ON c.collection_uid=d.collection_uid WHERE c.classroom_id<>v_classroom_id) THEN RAISE EXCEPTION 'A canonical collection_uid belongs to another classroom'; END IF; END $$;
WITH target AS (SELECT id AS classroom_id FROM public.classrooms WHERE school_year=2026 AND grade_level=5 AND name='5학년 4반' AND is_active ORDER BY id LIMIT 1) INSERT INTO public.character_collections(collection_uid,classroom_id,name,description,collection_class,is_active,is_visible,sort_order,metadata) SELECT d.collection_uid,t.classroom_id,d.name,d.description,d.collection_class,d.is_active,d.is_visible,d.sort_order,jsonb_build_object('source_sheet','컬렉션_34종','source_file','BRAND_2.0_현재적용_최신_컬렉션_34종(2).tsv','source_sha256','e6ad02caa122842acb7e295f81d78fbaee20fd62b6f3bc9e49d2d4225d161686','source_applied_at',now()) FROM desired_character_collections d CROSS JOIN target t ON CONFLICT(collection_uid) DO UPDATE SET classroom_id=EXCLUDED.classroom_id,name=EXCLUDED.name,description=EXCLUDED.description,collection_class=EXCLUDED.collection_class,is_active=EXCLUDED.is_active,is_visible=EXCLUDED.is_visible,sort_order=EXCLUDED.sort_order,metadata=public.character_collections.metadata || EXCLUDED.metadata,updated_at=now();
UPDATE public.character_collection_members m SET is_active=false,metadata=m.metadata || jsonb_build_object('canonical_sync','COLLECTION_34_20260907','canonical_active',false),updated_at=now() FROM public.character_collections c JOIN desired_character_collections d ON d.collection_uid=c.collection_uid WHERE m.collection_id=c.id AND m.is_active AND NOT EXISTS(SELECT 1 FROM desired_character_collection_members dm JOIN public.characters ch ON ch.character_uid=dm.character_uid WHERE dm.collection_uid=d.collection_uid AND ch.id=m.character_id);
UPDATE public.character_collection_rewards r SET is_active=false,metadata=r.metadata || jsonb_build_object('canonical_sync','COLLECTION_34_20260907','canonical_active',false),updated_at=now() FROM public.character_collections c JOIN desired_character_collections d ON d.collection_uid=c.collection_uid JOIN public.buff_effect_catalog e ON e.effect_code=d.effect_code WHERE r.collection_id=c.id AND r.effect_id<>e.id AND r.is_active;
DO $$ DECLARE v_bad integer; BEGIN SELECT count(*) INTO v_bad FROM desired_character_collections d LEFT JOIN public.character_collections c ON c.collection_uid=d.collection_uid WHERE c.id IS NULL OR c.name IS DISTINCT FROM d.name OR c.description IS DISTINCT FROM d.description OR c.collection_class IS DISTINCT FROM d.collection_class OR c.is_active IS DISTINCT FROM d.is_active OR c.is_visible IS DISTINCT FROM d.is_visible OR c.sort_order IS DISTINCT FROM d.sort_order; IF v_bad<>0 THEN RAISE EXCEPTION 'Collection sync postcheck failed: % collection rows mismatch',v_bad; END IF; SELECT count(*) INTO v_bad FROM desired_character_collection_members dm LEFT JOIN public.character_collections c ON c.collection_uid=dm.collection_uid LEFT JOIN public.characters ch ON ch.character_uid=dm.character_uid LEFT JOIN public.character_collection_members m ON m.collection_id=c.id AND m.character_id=ch.id AND m.is_active AND m.sort_order=dm.sort_order WHERE m.id IS NULL; IF v_bad<>0 THEN RAISE EXCEPTION 'Collection sync postcheck failed: % canonical members missing',v_bad; END IF; SELECT count(*) INTO v_bad FROM public.character_collections c JOIN desired_character_collections d ON d.collection_uid=c.collection_uid JOIN public.character_collection_members m ON m.collection_id=c.id AND m.is_active JOIN public.characters ch ON ch.id=m.character_id WHERE NOT EXISTS(SELECT 1 FROM desired_character_collection_members dm WHERE dm.collection_uid=d.collection_uid AND dm.character_uid=ch.character_uid); IF v_bad<>0 THEN RAISE EXCEPTION 'Collection sync postcheck failed: % stale active members remain',v_bad; END IF; SELECT count(*) INTO v_bad FROM desired_character_collections d LEFT JOIN public.character_collections c ON c.collection_uid=d.collection_uid LEFT JOIN public.buff_effect_catalog e ON e.effect_code=d.effect_code LEFT JOIN public.character_collection_rewards r ON r.collection_id=c.id AND r.effect_id=e.id AND r.is_active AND r.effect_value=d.effect_value WHERE r.id IS NULL; IF v_bad<>0 THEN RAISE EXCEPTION 'Collection sync postcheck failed: % canonical rewards mismatch',v_bad; END IF; SELECT count(*) INTO v_bad FROM public.character_collections c JOIN desired_character_collections d ON d.collection_uid=c.collection_uid JOIN public.character_collection_rewards r ON r.collection_id=c.id AND r.is_active JOIN public.buff_effect_catalog e ON e.id=r.effect_id WHERE e.effect_code<>d.effect_code; IF v_bad<>0 THEN RAISE EXCEPTION 'Collection sync postcheck failed: % stale active rewards remain',v_bad; END IF; END $$;
COMMIT;