INSERT INTO public.character_collection_members(collection_id,character_id,is_active,sort_order,metadata) SELECT c.id,ch.id,true,dm.sort_order,jsonb_build_object('canonical_sync','COLLECTION_34_20260907','canonical_active',true,'source_sha256','e6ad02caa122842acb7e295f81d78fbaee20fd62b6f3bc9e49d2d4225d161686') FROM desired_character_collection_members dm JOIN public.character_collections c ON c.collection_uid=dm.collection_uid JOIN public.characters ch ON ch.character_uid=dm.character_uid ON CONFLICT(collection_id,character_id) DO UPDATE SET is_active=true,sort_order=EXCLUDED.sort_order,metadata=public.character_collection_members.metadata || EXCLUDED.metadata,updated_at=now();
INSERT INTO public.character_collection_rewards(collection_id,effect_id,effect_value,is_active,sort_order,metadata) SELECT c.id,e.id,d.effect_value,true,1,jsonb_build_object('canonical_sync','COLLECTION_34_20260907','canonical_active',true,'source_sha256','e6ad02caa122842acb7e295f81d78fbaee20fd62b6f3bc9e49d2d4225d161686') FROM desired_character_collections d JOIN public.character_collections c ON c.collection_uid=d.collection_uid JOIN public.buff_effect_catalog e ON e.effect_code=d.effect_code ON CONFLICT(collection_id,effect_id) DO UPDATE SET effect_value=EXCLUDED.effect_value,is_active=true,sort_order=EXCLUDED.sort_order,metadata=public.character_collection_rewards.metadata || EXCLUDED.metadata,updated_at=now();
